#include <stdint.h>
#include <stdio.h>

void printf_fb(uint8_t* fb, uint32_t width, uint32_t height)
{
    for (uint32_t i = 0; i < width; i++) {
        for (uint32_t j = 0; j < height; j++)
            printf("%u,", fb[height * i + j]);
        printf("\n");
    }
}#include <stddef.h>

size_t countline(char *source)
{
	size_t count = 0;
	if (source == 0)
		return 0;
	do
	{
		if (*source == 0)
		{
			return 0;
		}
		if (*source == '\n')
			break;
		if (*source == '\r')
			continue;
		count++;
	} while (source++);
	return ++count;
}

char *readline(char *source, char *destination)
{
	if (source == 0)
		return 0;

	do
	{
		if (*source == 0)
		{
			*destination = 0;
			return 0;
		}
		if (*source == '\n')
			break;
		if (*source == '\r')
			continue;
		*destination = *source;
		destination++;
	} while (source++);
	*destination = 0;
	return ++source;
}#include "strings.h"
/**
 * modify text and replace umlauts with dual char ü -> ue
 * 
 * This is extremely hacky :/
 */
void convert_umlauts_inplace(char* text)
{
    size_t i = 0;
    while (text[i]) {
        if (text[i] == 0xc3) {
            i++;
            if (text[i] == 0xa4) { // ä
                text[i - 1] = 'a';
                text[i] = 'e';
            }
            if (text[i] == 0xb6) { // ö
                text[i - 1] = 'a';
                text[i] = 'e';
            }
            if (text[i] == 0xbc) { // ü
                text[i - 1] = 'a';
                text[i] = 'e';
            }
            if (text[i] == 0x2c) { // ß
                text[i - 1] = 's';
                text[i] = 'z';
            }
        }
        i++;
    }
}#ifndef PLATINENMACHER_HELPER_H_
#define PLATINENMACHER_HELPER_H_

/*
 * Read one line from string
 */
char *readline(char *source, char *destination);
size_t countline(char *source);

/*
 * use Printf to print out a framebuffer with numbers
 */
void printf_fb(uint8_t *fb, uint32_t width, uint32_t height);

void convert_umlauts_inplace(char* text);

#endif /* PLATINENMACHER_HELPER_H_ */

