    fn non_ascii_bytes_survive_intact() {
        // C is byte-oriented; slicing on \r / \n must not split UTF-8.
        let mut dst = String::new();
        let next = readline(Some("Grünstraße\r\nnext"), &mut dst);
        assert_eq!(dst, "Grünstraße");
